package vn.hust.restaurant.view;
import java.awt.*;import java.util.*;import javax.swing.*;import javax.swing.table.*;import vn.hust.restaurant.config.AppContext;import vn.hust.restaurant.model.Employee;
public class EmployeePanel extends JPanel implements Refreshable{private final AppContext ctx;private final JTextField search=new JTextField(18);private final DefaultTableModel model=Ui.model("ID","Mã","Họ tên","SĐT","Email","Vai trò","Làm việc","Username","Tài khoản");private final JTable table=new JTable(model);private java.util.List<Employee>data=java.util.List.of();public EmployeePanel(AppContext c){ctx=c;setLayout(new BorderLayout());JButton add=new JButton("Thêm"),edit=new JButton("Sửa"),account=new JButton("Cấp/đặt lại tài khoản"),lock=new JButton("Khóa/Mở"),reload=new JButton("Tìm");add(Ui.toolbar(new JLabel("Tìm:"),search,reload,add,edit,account,lock),BorderLayout.NORTH);add(new JScrollPane(table),BorderLayout.CENTER);reload.addActionListener(e->refresh());add.addActionListener(e->edit(null));edit.addActionListener(e->{int r=table.getSelectedRow();if(r>=0)edit(data.get(r));});account.addActionListener(e->account());lock.addActionListener(e->{int r=table.getSelectedRow();if(r>=0)Ui.run(this,()->{Employee x=data.get(r);ctx.employees.lock(x.id(),!"BI_KHOA".equals(x.accountStatus()));refresh();});});refresh();}
 public void refresh(){Ui.run(this,()->{data=ctx.employees.list(search.getText());model.setRowCount(0);for(Employee x:data)model.addRow(new Object[]{x.id(),x.code(),x.fullName(),x.phone(),x.email(),x.role(),x.workStatus(),x.username(),x.accountStatus()});});}
 private void edit(Employee x){JTextField code=Ui.field(x==null?"NV"+(System.currentTimeMillis()%100000):x.code(),12),name=Ui.field(x==null?"":x.fullName(),18),cccd=Ui.field(x==null?"":x.citizenId(),14),phone=Ui.field(x==null?"":x.phone(),12),email=Ui.field(x==null?"":x.email(),18),addr=Ui.field(x==null?"":x.address(),20);JComboBox<String>role=new JComboBox<>(new String[]{"CHU_NHA_HANG","PHUC_VU","DAU_BEP","THU_NGAN"});if(x!=null)role.setSelectedItem(x.role());Object[]f={"Mã",code,"Họ tên",name,"CCCD",cccd,"SĐT",phone,"Email",email,"Địa chỉ",addr,"Vai trò",role};if(JOptionPane.showConfirmDialog(this,f,x==null?"Thêm nhân viên":"Sửa nhân viên",JOptionPane.OK_CANCEL_OPTION)==JOptionPane.OK_OPTION)Ui.run(this,()->{ctx.employees.save(new Employee(x==null?0:x.id(),code.getText(),name.getText(),cccd.getText(),phone.getText(),email.getText(),addr.getText(),String.valueOf(role.getSelectedItem()),x==null?"DANG_LAM":x.workStatus(),x==null?null:x.username(),x==null?null:x.accountStatus()));refresh();});}
 private void account(){int r=table.getSelectedRow();if(r<0)return;Employee x=data.get(r);JTextField u=Ui.field(x.username()==null?x.code().toLowerCase():x.username(),15);JPasswordField p=new JPasswordField("123456",15);if(JOptionPane.showConfirmDialog(this,new Object[]{"Username",u,"Mật khẩu",p},"Cấp/đặt lại tài khoản",JOptionPane.OK_CANCEL_OPTION)==JOptionPane.OK_OPTION)Ui.run(this,()->{ctx.employees.account(x.id(),u.getText(),new String(p.getPassword()));Ui.info(this,"Đã cập nhật tài khoản");refresh();});}}
